-- =====================================================================
-- 藏品示例数据（演示 / 答辩用）
-- 适用：relic_db（MySQL，3307）
-- 执行：mysql -h127.0.0.1 -P3307 -uroot -p --default-character-set=utf8 relic_db < sql/seed_relics.sql
--
-- 说明：
--   1. 全部使用固定 id，脚本可重复执行（ON DUPLICATE KEY UPDATE），不会产生重复数据；
--   2. 12 件藏品覆盖现有 5 个分类（陶瓷 / 青铜 / 书画 / 玉器 / 漆器），
--      10 件在库、1 件出库、1 件修复中；
--   3. 每件藏品关联一条 relic_attachment（file_type = 1 藏品影像），
--      file_path 为 uploads 下的相对路径，接口据此返回封面地址；
--   4. 同步写入 2 个库房、8 个仓位与溯源记录，保证详情页时间线完整。
-- =====================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
-- 一、库房
-- ---------------------------------------------------------------------
