 '00000000000000000000000000000001', '系统管理员', '2026-09-05 09:40:00', '00000000000000000000000000000001', '系统管理员', '2026-09-15 10:32:00', 0, 0, NULL),

('00000000000000000000000000030003', 'TC-0003', '汝窑天青釉洗', '00000000000000000000000000000101', NULL, '北宋', '瓷', '口径 13.5cm，高 3.8cm',
