-- ---------------------------------------------------------------------
-- 六、校验
-- ---------------------------------------------------------------------
SELECT '库房' AS 对象, COUNT(*) AS 条数 FROM `relic_warehouse` WHERE `is_deleted` = 0
UNION ALL SELECT '仓位', COUNT(*) FROM `relic_storage_position` WHERE `is_deleted` = 0
UNION ALL SELECT '藏品', COUNT(*) FROM `relic_info` WHERE `is_deleted` = 0
UNION ALL SELECT '影像附件', COUNT(*) FROM `relic_attachment` WHERE `is_deleted` = 0
UNION ALL SELECT '溯源记录', COUNT(*) FROM `relic_trace_record` WHERE `is_deleted` = 0;
